//! Build-time configuration, generated by `build.rs` from `settings.toml`
//! (display, server, slideshow) and `secrets.toml` (Wi-Fi credentials).
//!
//! Everything here is a constant, so the display size can size static
//! buffers, and settings that aren't used compile away.

/// A Wi-Fi network from `secrets.toml`.
pub struct WifiNetwork {
    pub ssid: &'static str,
    /// Empty for an open network.
    pub password: &'static str,
}

/// The display hardware (`[display] type`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum DisplayType {
    /// Waveshare ESP32-S3-Touch-LCD-7: RGB panel, GT911 touch, CH422G expander.
    WaveshareEsp32S3TouchLcd7,
}

/// How far the picture is turned clockwise on the panel (`[display] rotation`).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Rotation {
    Deg0,
    Deg90,
    Deg180,
    Deg270,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Transition {
    Crossfade,
    Cut,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Scale {
    /// Show the whole picture, with borders.
    Fit,
    /// Fill the screen, cropping the picture.
    Fill,
}

include!(concat!(env!("OUT_DIR"), "/config.rs"));

/// The screen as the viewer sees it: the panel size, turned by the rotation.
pub const fn logical_size() -> (usize, usize) {
    match display::ROTATION {
        Rotation::Deg0 | Rotation::Deg180 => (display::WIDTH, display::HEIGHT),
        Rotation::Deg90 | Rotation::Deg270 => (display::HEIGHT, display::WIDTH),
    }
}

/// Maps a point on the viewer's (logical) screen to its index in a
/// panel-order pixel buffer. The inverse of [`panel_to_logical`].
#[inline(always)]
pub fn logical_to_panel_index(x: usize, y: usize) -> usize {
    use display::{HEIGHT, WIDTH};
    let (px, py) = match display::ROTATION {
        Rotation::Deg0 => (x, y),
        Rotation::Deg90 => (WIDTH - 1 - y, x),
        Rotation::Deg180 => (WIDTH - 1 - x, HEIGHT - 1 - y),
        Rotation::Deg270 => (y, HEIGHT - 1 - x),
    };
    py * WIDTH + px
}

/// Maps a panel pixel to the viewer's (logical) coordinates.
#[inline(always)]
pub fn panel_to_logical(x: usize, y: usize) -> (usize, usize) {
    use display::{HEIGHT, WIDTH};
    match display::ROTATION {
        Rotation::Deg0 => (x, y),
        Rotation::Deg90 => (y, WIDTH - 1 - x),
        Rotation::Deg180 => (WIDTH - 1 - x, HEIGHT - 1 - y),
        Rotation::Deg270 => (HEIGHT - 1 - y, x),
    }
}
